"""Measured alignment comparisons, kept separate from the production proposal."""
import html
import json
import statistics
from pathlib import Path

HERE=Path(__file__).resolve().parent
LABELS={'compact96':'96 compact','base128_stride96':'96 · bloc aligné 128','pad128_align64':'128 · alignement 64','pad128_align128':'128 · alignement 128','inline_meta128':'128 · méta intégrée','split32':'32 chaud + 64 froid','hot32_packed':'États de 32 groupés','hot128_isolated':'État isolé dans 128'}
OPS={'scan_state':'Parcours des états','scan_full':'Parcours des lignes complètes','random_state':'État par position aléatoire','id_state':'ID → index → état','state_and_meta':'État et métadonnées','update_previous':'Mise à jour avec précédente'}
def esc(s):return html.escape(str(s))
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def load():return json.loads((HERE/'alignement-banc/sorties/resultats.json').read_text())

def body():
    d=load();m=d['metadata'];large=max(d['dimensions'],key=lambda x:x['n']);serial=[r for r in d['measurements'] if r['kind']=='sample' and r['dataset']==large['dataset'] and r['scale']==large['scale']]
    scan={r['variant']:r['median_ns'] for r in serial if r['operation']=='scan_state'}
    meta={r['variant']:r['median_ns'] for r in serial if r['operation']=='state_and_meta'}
    parallel={(r['variant'],r['pattern']):r['median_ns'] for r in d['measurements'] if r['kind']=='parallel' and r['threads']==4 and r['operation']=='state_words'}
    dimopts=''.join(f'<option value="{esc(x["dataset"])}|{x["scale"]}"'+(' selected' if x['dataset']=='somme-detail' and x['scale']==100 else '')+f'>{esc(x["dataset"])} ×{x["scale"]} · {x["n"]:,} lignes</option>' for x in d['dimensions'])
    opopts=''.join(f'<option value="{key}">{esc(label)}</option>' for key,label in OPS.items())
    text='''<p class="lead">Partager une ligne de cache n’écrase aucune donnée. Le coût apparaît lorsque plusieurs cœurs travaillent sur cette même ligne. Nous avons comparé la taille des tableaux, leur mémoire réelle et la vitesse de six rangements, puis testé des écrivains concurrents.</p>
<div class="notice"><b>Nouvelle campagne mesurée, sans appareil.</b> Les noyaux de rangement conservent le même courant, précédent distinct, deux dates et contraintes. La sonde concurrente utilise des mots atomiques : elle étudie le partage de cache, sans remplacer le verrou ni prouver une migration du Hub.</div>'''
    text+=f'<p>Cache annoncé par l’hôte : <b>{m["host_cpu_observation"].get("hw.cachelinesize","non exposé")} octets</b>. L’invité Linux ne publie pas ici sa géométrie de cache. Quatre vCPU sont disponibles ; les threads sont fixés aux CPU logiques 0–3 et leur placement est contrôlé. Cela n’isole pas les cœurs physiques de l’hôte.</p>'
    text+='''<h3>Voir exactement ce qui partage une ligne de cache</h3><div class="controls"><div><label for="cacheline-choice">Géométrie illustrée</label><select id="cacheline-choice"><option value="128">Lignes de cache de 128 octets</option><option value="64">Lignes de cache de 64 octets</option></select></div></div><div id="alignment-geometry"></div>
<p>Ces schémas supposent une base à zéro, alignée sur la taille de cache sélectionnée. Le réglage 64 illustre une autre géométrie : les mesures n’ont pas été réalisées sur une machine à cache de 64 octets. Aligner le début d’un tableau ne change pas le pas de ses éléments de 96 octets. En Rust, le pas d’un tableau est <code>size_of</code> ; un type de 96 octets auquel on impose un alignement de 64 ou 128 atteint ici 128 octets. <a href="https://doc.rust-lang.org/reference/type-layout.html">Règles Rust de taille et d’alignement</a>.</p>
<h3>Le coût par objet, avant l’index ID et les contenus variables</h3>'''
    text+=table(['Rangement','État + contraintes','Méta','Slot','Total utile / canonique'],[
        ('96 compact','96','32 à côté','16','144 octets'),
        ('96, blocs de quatre alignés 128','96','32 à côté','16','144 + au plus 3 lignes réservées en fin de tableau'),
        ('128 avec remplissage','128 dont 32 inutilisés','32 à côté','16','176 octets'),
        ('128 avec Meta32 intégrée','96 + Meta32 dans la même ligne','déjà comprise','16','144 octets'),
        ('Chaud/froid séparés','32 + 32 + 32','32 à côté','16','144 octets'),
        ('Alias existant, inchangé','Alias32 : 32','32','16','80 octets'),
    ])
    text+='<p><b>128 avec remplissage ajoute 33,3 % à la seule table des lignes, mais 22,2 % au socle 144 → 176.</b> Intégrer les 32 octets de métadonnées déjà nécessaires garde au contraire le total utile à 144. Les réservations exactes, l’index et les pages anonymes mesurées sont affichés ci-dessous ; aucun de ces nombres n’est le coût de tout le moteur.</p>'
    text+='''<h3>Mémoire et vitesse sur les mêmes charges</h3><div class="controls"><div><label for="alignment-dataset">Projection des formes Home Assistant</label><select id="alignment-dataset">'''+dimopts+'''</select></div><div><label for="alignment-operation">Opération mesurée</label><select id="alignment-operation">'''+opopts+'''</select></div></div><div id="alignment-serial-chart"></div><div id="alignment-memory"></div>
<p>Les deux inventaires A/B, leur somme et leurs formes détaillées déterminent seulement les dimensions. Les noyaux emploient des entiers synthétiques ; ils ne rejouent pas les valeurs et intégrations HA. Chaque variante conserve les mêmes informations, les mêmes requêtes et le même index. Le bloc aligné de quatre ajoute son arithmétique d’accès. La séparation chaud/froid garde ici Numeric32 sur chaque ligne pour comparer une information égale ; ce n’est pas la variante à annexes numériques clairsemées de l’ancien budget. Cold32 porte encore la révision et les flags : une mise à jour de l’état touche donc aussi cette table, qui n’est pas entièrement froide en écriture.</p>'''
    text+=f'<p>Sur {large["n"]:,} lignes : parcours des états, 96 compact <b>{scan["compact96"]:.3f} ns</b>, 128 aligné <b>{scan["pad128_align128"]:.3f} ns</b>, chaud/froid <b>{scan["split32"]:.3f} ns</b>. Lire état + méta donne <b>{meta["compact96"]:.3f} ns</b> pour 96 + méta séparée et <b>{meta["inline_meta128"]:.3f} ns</b> pour la méta intégrée. Ce sont les médianes de cette campagne ; les étendues min–max restent visibles. Aucun classement universel ne découle de ces résultats.</p>'
    text+='''<h3>Écritures concurrentes : le placement compte aussi</h3><div class="controls"><div><label for="alignment-threads">Écrivains</label><select id="alignment-threads"><option value="1">1 thread</option><option value="2">2 threads</option><option value="4" selected>4 threads</option></select></div><div><label for="alignment-parallel-op">Travail par point</label><select id="alignment-parallel-op"><option value="state_words">Quatre mots d’état</option><option value="all_words">Stress : douze mots</option></select></div></div><div id="alignment-parallel-chart"></div><div id="alignment-parallel-table"></div>
<p><b>Alternés</b> : les threads écrivent des points voisins. <b>Par blocs</b> : chaque thread possède sa tranche contiguë, avec frontières par groupes de 256 points. Le nombre d’opérations est identique. Ces durées sont divisées par toutes les opérations de tous les threads : elles expriment le débit agrégé, pas la latence d’une commande. La sonde normale ne touche que courant, précédent et deux dates ; le stress écrit aussi les données froides et n’est pas une mise à jour domotique normale.</p>
<p>Les Hot32 naturels ne garantissent pas un début de tableau aligné sur le cache : quelques bordures de tranches peuvent encore partager une ligne. La répartition par blocs réduit l’exposition dans ces mesures, sans prouver son absence absolue. Pour garantir des frontières isolées, il faut aussi aligner la base et les limites des tranches sur la géométrie cible.</p>'''
    text+=f'<p>Avec quatre écrivains, les états Hot32 groupés donnent une médiane de <b>{parallel[("hot32_packed","interleaved")]:.3f} ns/op</b> en alternance et <b>{parallel[("hot32_packed","blocks")]:.3f} ns/op</b> par blocs. Isoler chaque état dans 128 octets donne <b>{parallel[("hot128_isolated","interleaved")]:.3f} ns/op</b> en alternance, mais consomme quatre fois la place du seul Hot32. Le placement par blocs évite ce remplissage dans cette sonde. Ces observations sont compatibles avec un effet de partage de cache ; aucun compteur matériel d’invalidation n’a été mesuré.</p>'
    text+='''<h3>Que mettre dans les 32 octets supplémentaires ?</h3><div class="recommend"><b>La piste la plus utile à qualifier est Meta32 intégrée.</b> Elle déplace une donnée déjà prévue au lieu d’en inventer une nouvelle. Le tableau séparé de métadonnées canoniques doit alors être supprimé pour obtenir l’économie ; les alias gardent leur rangement propre.</div>
<pre>#[repr(C, align(128))]
struct Ligne128 {
    etat: Row96,    // 0..96 : mêmes informations qu’aujourd’hui
    meta: Meta32,   // 96..128 : huit références u32 déjà prévues
}                  // 128 utiles, aucune réserve vide</pre>'''
    text+=table(['Les huit références de Meta32','À quoi elles servent'],[
        ('label / native_key','Nom choisi et clé native, vers leurs pools partagés.'),
        ('location / policy','Lieu et politique ; les protections physiques restent celles du Hub.'),
        ('read_plan / write_plan','Plans déterministes de lecture et d’écriture.'),
        ('executable / extra','Contrat exécutable et extension typée, selon le contrat final.'),
    ])
    text+='''<p>La valeur précédente et les deux dates sont déjà dans Row96 : les répéter gaspillerait cette place. Ajouter systématiquement un historique, un mutex ou une commande souhaitée n’est pas justifié par ces tests. Les données variables, historiques et commandes en attente gardent leur budget séparé. Des références d’exécution supplémentaires ne se justifient que sur les points qui les utilisent, avec un contrat et des mesures.</p>
<h3>Choix à retenir après ces essais</h3>'''
    text+=table(['Charge dominante','Piste','Avantage / limite'],[
        ('Écriture centralisée et parcours séquentiels','Garder 96 compact comme référence.','Pas de taxe de remplissage ; le multicœur réel du Hub reste à qualifier.'),
        ('Lecture fréquente de la valeur avec son contexte','Qualifier 128 alignés avec Meta32 intégrée.','Même socle 144 ; métadonnées plus proches. Migration des slots et compactions à développer.'),
        ('Parcours massifs du seul état','Chaud/froid séparés.','Plus dense pour le chaud ; accès complet et mises à jour touchent plusieurs tables.'),
        ('Plusieurs écrivains','Propriétaire unique et tranches par écrivain.','Évite les voisins écrits en alternance. Une zone logique chevauchante ne suffit pas à garantir cette propriété.'),
        ('Isoler chaque point sans contenu utile en plus','128 avec remplissage seulement si un besoin mesuré le justifie.','Mémoire supplémentaire et scans parfois plus lents ; pas de passage global automatique.'),
    ])
    text+='''<p>Ces résultats ne changent pas encore le stockage du Hub. Il faut publier les index et slots cohérents lors des déplacements ; une future ligne intégrant Meta32 doit y accéder par indice stable, sans conserver de pointeur de Vec. Le précédent reste partagé par les alias. Un écrivain par tranche impose une règle explicite lors des compactions.</p>
<details><summary>Protocole, preuves et reproduction</summary>'''
    text+=table(['Contrôle','Capture'],[
        ('Tailles et sémantique','6 variantes séquentielles et 5 formes atomiques ; transition comparée au vrai Bank.'),
        ('Mesures','336 groupes × 9 rondes ; 3 processus indépendants × 3 rondes.'),
        ('Résultats identiques',f'{d["tests"]["cross_layout_checksum_groups"]} groupes de checksums comparés entre rangements.'),
        ('Environnement',f'{m["cpus"]} vCPU, affinités {m["cpuset"]}, mémoire {m["memory"]}, réseau {m["network"]}.'),
        ('Compilation',m['flags']),('Image figée',m['image_id']),
    ])
    text+='''<p>Le compilateur est à optimisation 3 pour cette campagne ; les anciens bancs utilisaient une optimisation de taille. L’accès ID emploie un index commun vers une position, sans tous les contrôles de génération et d’incarnation du Bank. Les valeurs absolues de ces campagnes ne sont pas interchangeables. Les scans et requêtes sont chauffés ; l’ordre des variantes est inversé au deuxième processus. Les fils concurrents, leurs tableaux et leurs barrières sont préparés avant le chronomètre ; libération et attente des barrières restent incluses. Les mots atomiques relaxés évitent une course mémoire mais ne rendent pas une observation complète atomique. Les temps de construction, garde, réseau, journal et notifications ne sont pas couverts.</p>
<p>Sources et résultats : <a href="../../../tools/memoire-structure-v6/alignement-banc/README.md">protocole et commande</a> · <a href="../../../tools/memoire-structure-v6/alignement-banc/main.rs">Rust du banc</a> · <a href="../../../tools/memoire-structure-v6/alignement-banc/sorties/resultats.json">JSON complet</a> · <a href="../../../tools/memoire-structure-v6/alignement-banc/sorties/echantillons.jsonl">échantillons bruts</a>. Les mesures sont locales au nouvel environnement Linux ARM64 virtualisé, pas une validation d’autres processeurs ni du moteur complet.</p></details>'''
    return text

def script():
    d=load()
    payload={'labels':LABELS,'ops':OPS,'dimensions':d['dimensions'],'measurements':[{k:v for k,v in r.items() if k!='samples'} for r in d['measurements']],'memory':d['memory']}
    return SCRIPT.replace('__ALIGNMENT__',json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))

SCRIPT=r'''
(()=>{'use strict';const d=__ALIGNMENT__,safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:3});
const table=(head,rows)=>'<div class="scroll"><table><thead><tr>'+head.map(x=>'<th>'+safe(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+safe(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
function bars(rows){const max=Math.max(...rows.map(r=>r[1]),1e-9),h=45+rows.length*37;return '<div class="diagram"><svg role="img" aria-label="Temps mesuré par opération" viewBox="0 0 1050 '+h+'"><title>Temps mesuré, axe linéaire partant de zéro</title><text x="270" y="20">0 → '+fmt(max)+' ns/op · axe linéaire</text>'+rows.map((r,i)=>'<text x="8" y="'+(57+i*37)+'">'+safe(r[0])+'</text><rect x="270" y="'+(37+i*37)+'" height="25" width="'+(r[1]/max*590)+'" fill="'+(r[2]||'#276651')+'"/><text x="878" y="'+(57+i*37)+'">'+fmt(r[1])+' ns/op</text>').join('')+'</svg></div>';}
function geometry(){const line=Number(document.getElementById('cacheline-choice').value);document.getElementById('alignment-geometry').innerHTML=[[96,'96 compacts : les objets restent contigus',false],[128,'128 alignés : 32 octets de remplissage',false],[128,'128 alignés : les 32 octets deviennent Meta32',true]].map(([stride,title,meta])=>{const total=stride*4,scale=900/total;let rects='';for(let i=0;i<4;i++){rects+='<rect x="'+(20+i*stride*scale)+'" y="40" height="40" width="'+(96*scale)+'" fill="'+['#25634e','#417997','#25634e','#417997'][i]+'"/><text x="'+(25+i*stride*scale)+'" y="105">'+String.fromCharCode(65+i)+' · 96</text>';if(stride===128)rects+='<rect x="'+(20+(i*stride+96)*scale)+'" y="40" height="40" width="'+(32*scale)+'" fill="'+(meta?'#d6ae65':'#c8cec6')+'"/><title>32 octets '+(meta?'de métadonnées':'réservés')+'</title>';}
for(let b=0;b<=total;b+=line)rects+='<path d="M'+(20+b*scale)+' 25V85" stroke="#1c3329" stroke-dasharray="3 3"/><text x="'+(20+b*scale)+'" y="20">'+b+'</text>';return '<div class="diagram"><b>'+safe(title)+'</b><svg role="img" aria-label="'+safe(title)+'" viewBox="0 0 960 120"><title>'+safe(title)+' ; traits de cache tous les '+line+' octets</title>'+rects+'</svg><p class="muted">Traits : frontières des lignes de cache. Vert/bleu : objets distincts ; or : Meta32 ; gris : remplissage.</p></div>';}).join('');}
function serial(){const [dataset,scaleText]=document.getElementById('alignment-dataset').value.split('|'),scale=Number(scaleText),op=document.getElementById('alignment-operation').value;const rows=d.measurements.filter(r=>r.kind==='sample'&&r.dataset===dataset&&r.scale===scale&&r.operation===op);document.getElementById('alignment-serial-chart').innerHTML=bars(rows.map(r=>[d.labels[r.variant],r.median_ns]))+table(['Rangement','Médiane, ns/op','Min–max, ns/op'],rows.map(r=>[d.labels[r.variant],fmt(r.median_ns),fmt(r.min_ns)+'–'+fmt(r.max_ns)]));
const mem=rows.map(r=>{const captures=d.memory.filter(m=>m.dataset===dataset&&m.scale===scale&&m.variant===r.variant),x=captures[0],rss=captures.map(v=>v.process_bytes.RssAnon).sort((a,b)=>a-b);return [d.labels[r.variant],fmt(x.requested_rows_meta_bytes/1048576),fmt(x.slots_bytes/1048576),fmt(x.index_requested_bytes/1048576),fmt(rss[1]/1048576),x.arrays.map(a=>a.name+': '+a.base_mod128).join(' ; ')];});document.getElementById('alignment-memory').innerHTML=table(['Rangement','Lignes + méta, Mio demandés','Slots, Mio','Index, Mio','Pages anonymes, Mio · médiane','Base modulo 128 · 1er processus'],mem)+'<p class="muted">Les pages anonymes comprennent plusieurs de ces postes et d’autres besoins du processus : ne pas les additionner aux colonnes d’allocation. Le JSON conserve capacités, pages RSS et pic. La copie de fin du bloc de quatre est incluse dans ses réservations.</p>';}
function parallel(){const threads=Number(document.getElementById('alignment-threads').value),op=document.getElementById('alignment-parallel-op').value,rows=d.measurements.filter(r=>r.kind==='parallel'&&r.threads===threads&&r.operation===op);document.getElementById('alignment-parallel-chart').innerHTML=bars(rows.map(r=>[d.labels[r.variant]+' · '+(r.pattern==='blocks'?'blocs':'alternés'),r.median_ns,r.pattern==='blocks'?'#276651':'#b58443']));document.getElementById('alignment-parallel-table').innerHTML=table(['Rangement','Répartition','ns/op agrégé','Min–max','Débit agrégé, millions op/s'],rows.map(r=>[d.labels[r.variant],r.pattern==='blocks'?'blocs':'alternés',fmt(r.median_ns),fmt(r.min_ns)+'–'+fmt(r.max_ns),fmt(1000/r.median_ns)]));}
for(const id of ['alignment-dataset','alignment-operation'])document.getElementById(id).addEventListener('change',serial);for(const id of ['alignment-threads','alignment-parallel-op'])document.getElementById(id).addEventListener('change',parallel);document.getElementById('cacheline-choice').addEventListener('change',geometry);geometry();serial();parallel();window.alignmentReport={data:d,geometry,serial,parallel};})();
'''
